#include "platform/secrets.hpp"
#include "platform/secret_envelope.hpp"
#include "platform/secret_identity.hpp"
#include <windows.h>
#include <dpapi.h>
#include <filesystem>
#include <fstream>
#include <vector>
#include <memory>
#include <span>
#include <cstddef>
